/**
 * GitHub REST helpers backed by `@octokit/rest`.
 *
 * Channel hooks should prefer `ctx.github` / `ctx.thread`. Use
 * {@link createGitHubOctokit} (or `ctx.github.getOctokit()`) when you need
 * typed Octokit methods directly.
 */
import { createAppAuth } from "@octokit/auth-app";
import { Octokit } from "@octokit/rest";
import { hasGitHubAppCredentials, resolveCredentialValue, resolveGitHubAccessToken, resolveGitHubAppId, resolveGitHubInstallationId, resolveGitHubPrivateKey, } from "./auth.js";
import { getCursorAccountGithubProxyTransport, githubRepoFromOctokitRequest, isCursorAccountGithubTokenResolver, } from "./cursor-account.js";
export class GitHubApiError extends Error {
    constructor(input) {
        super(`GitHub ${input.method} ${input.path} failed with HTTP ${input.status}.`);
        this.name = "GitHubApiError";
        this.body = input.body;
        this.method = input.method;
        this.path = input.path;
        this.status = input.status;
    }
}
const GITHUB_ENTERPRISE_CLOUD_HOST = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.ghe\.com$/;
/**
 * REST origin for a GitHub Enterprise Cloud tenant. github.com and any
 * other host stay on the client's default API. An explicit `apiBaseUrl`
 * still wins, so a test transport is not rewritten.
 */
export function githubEnterpriseCloudApiBaseUrl(host) {
    if (host === undefined) {
        return undefined;
    }
    const normalized = host.trim().toLowerCase();
    return GITHUB_ENTERPRISE_CLOUD_HOST.test(normalized) ? `https://api.${normalized}` : undefined;
}
/**
 * Build an authenticated Octokit client.
 *
 * Prefer explicit bearer tokens, then GitHub App installation auth (when App
 * credentials + an installation id are available), then local PAT /
 * `gh auth token`. App auth uses `@octokit/auth-app` so Octokit refreshes
 * installation tokens itself.
 *
 * `host` selects `https://api.<tenant>.ghe.com` for a direct client. A
 * Cursor github-proxy transport keeps its own base URL: the proxy chooses
 * the upstream from the deployment's verified tenant.
 */
export async function createGitHubOctokit(input) {
    const transport = githubOctokitTransport(input.api);
    const enterpriseBaseUrl = transport.baseUrl === undefined ? githubEnterpriseCloudApiBaseUrl(input.host) : undefined;
    const dynamicToken = isCursorAccountGithubTokenResolver(input.credentials?.token)
        ? input.credentials.token
        : isCursorAccountGithubTokenResolver(input.credentials?.installationToken)
            ? input.credentials.installationToken
            : undefined;
    if (dynamicToken !== undefined) {
        // Host-bound backend proxy: target the forwarder and attach the repo
        // scope headers; the resolved token is the Cursor API key, not a raw
        // GitHub credential. Authored `api.apiBaseUrl` still wins (test seam).
        const proxyTransport = getCursorAccountGithubProxyTransport(dynamicToken);
        const octokit = new Octokit({
            ...transport,
            // The proxy base wins over the tenant API. A direct dynamic token
            // (no proxy) follows the tenant host.
            baseUrl: transport.baseUrl ?? proxyTransport?.apiBaseUrl ?? enterpriseBaseUrl,
        });
        octokit.hook.before("request", async (request) => {
            const token = await resolveCredentialValue(dynamicToken);
            if (token === undefined) {
                throw new Error("githubChannel: dynamic GitHub token is unavailable.");
            }
            request.headers.authorization = `Bearer ${token}`;
            if (proxyTransport !== undefined) {
                Object.assign(request.headers, proxyTransport.headers);
                const existingRepos = request.headers["x-cursor-github-repos"];
                if (typeof existingRepos !== "string" || existingRepos.trim() === "") {
                    const repo = githubRepoFromOctokitRequest(request);
                    if (repo !== undefined) {
                        request.headers["x-cursor-github-repos"] = repo;
                    }
                }
            }
        });
        if (proxyTransport !== undefined) {
            // GitHub pagination Link values are absolute /repositories/{id} URLs.
            // Following one skips baseUrl, so the Cursor API key is sent to GitHub
            // with no repo scope. Point those URLs at /repos/{owner}/{repo} on this
            // proxy; the before hook then fills x-cursor-github-repos per page.
            octokit.hook.after("request", (response, options) => {
                const repo = githubRepoFromOctokitRequest(options);
                if (repo === undefined) {
                    return;
                }
                rewriteProxyPaginationLinkHeaders(response.headers, repo);
            });
        }
        return octokit;
    }
    const explicit = (await resolveCredentialValue(input.credentials?.token)) ??
        (await resolveCredentialValue(input.credentials?.installationToken));
    if (explicit !== undefined) {
        return new Octokit({ ...directTransport(transport, enterpriseBaseUrl), auth: explicit });
    }
    const installationId = await resolveGitHubInstallationId(input.installationId);
    if (installationId !== undefined && (await hasGitHubAppCredentials(input.credentials))) {
        const appId = await resolveGitHubAppId(input.credentials?.appId);
        const privateKey = await resolveGitHubPrivateKey(input.credentials?.privateKey);
        return new Octokit({
            ...directTransport(transport, enterpriseBaseUrl),
            authStrategy: createAppAuth,
            auth: {
                appId,
                privateKey,
                installationId,
            },
        });
    }
    // Local testing: ambient PAT / `gh auth token` when App creds are unset.
    return new Octokit({
        ...directTransport(transport, enterpriseBaseUrl),
        auth: await resolveGitHubAccessToken(input),
    });
}
function directTransport(transport, enterpriseBaseUrl) {
    const baseUrl = transport.baseUrl ?? enterpriseBaseUrl;
    return baseUrl === undefined ? transport : { ...transport, baseUrl };
}
const REPOSITORY_PAGINATION_PATH = /^\/(?:api\/v3\/)?repositories\/\d+(\/.*)?$/;
function rewriteProxyPaginationLinkHeaders(headers, repo) {
    for (const key of Object.keys(headers)) {
        if (key.toLowerCase() !== "link") {
            continue;
        }
        const value = headers[key];
        if (typeof value !== "string" || value.length === 0) {
            continue;
        }
        headers[key] = rewriteRepositoryLinkHeader(value, repo);
    }
}
function rewriteRepositoryLinkHeader(link, repo) {
    return link.replace(/<([^<>]+)>/g, (wrapped, rawUrl) => {
        const rewritten = rewriteAbsoluteRepositoryUrl(rawUrl.trim(), repo);
        return rewritten === undefined ? wrapped : `<${rewritten}>`;
    });
}
function rewriteAbsoluteRepositoryUrl(rawUrl, repo) {
    let parsed;
    try {
        parsed = new URL(rawUrl);
    }
    catch {
        return undefined;
    }
    const match = REPOSITORY_PAGINATION_PATH.exec(parsed.pathname);
    if (match === null) {
        return undefined;
    }
    const rest = match[1] ?? "";
    return `/repos/${repo}${rest}${parsed.search}${parsed.hash}`;
}
/** Shared `baseUrl` / custom `fetch` for every Octokit constructed here. */
function githubOctokitTransport(api) {
    return {
        baseUrl: api?.apiBaseUrl,
        request: api?.fetch === undefined ? undefined : { fetch: api.fetch },
    };
}
/**
 * Call a GitHub REST path with channel auth. Prefer typed Octokit methods via
 * {@link createGitHubOctokit} / `ctx.github.getOctokit()` when possible.
 */
export async function callGitHubApi(input) {
    if (input.options?.auth === false) {
        return requestWithOctokit(new Octokit(githubOctokitTransport(input.api)), input);
    }
    const octokit = await createGitHubOctokit({
        api: input.api,
        credentials: input.credentials,
        installationId: input.installationId,
    });
    return requestWithOctokit(octokit, input);
}
async function requestWithOctokit(octokit, input) {
    try {
        const route = `${input.method} ${normalizeRequestPath(input.path)}`;
        const response = await octokit.request(route, {
            ...(input.body ?? {}),
            ...(input.options?.headers === undefined ? {} : { headers: input.options.headers }),
        });
        return {
            // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the caller names the JSON shape; this helper cannot validate an arbitrary T
            body: response.data,
            ok: true,
            status: response.status,
        };
    }
    catch (error) {
        if (isOctokitRequestError(error)) {
            throw new GitHubApiError({
                body: error.response?.data,
                method: input.method,
                path: input.path,
                status: error.status,
            });
        }
        throw error;
    }
}
/** Create an issue or PR timeline comment. */
export async function createGitHubIssueComment(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = await octokit.rest.issues.createComment({
            owner: input.owner,
            repo: input.repo,
            issue_number: input.issueNumber,
            body: input.body,
        });
        return toPostedComment(response.data);
    }
    catch (error) {
        throw wrapOctokitError(error, "POST", `/repos/${input.owner}/${input.repo}/issues/${input.issueNumber}/comments`);
    }
}
/** Update an issue or PR timeline comment by id. */
export async function updateGitHubIssueComment(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = await octokit.rest.issues.updateComment({
            owner: input.owner,
            repo: input.repo,
            comment_id: input.commentId,
            body: input.body,
        });
        return toPostedComment(response.data);
    }
    catch (error) {
        throw wrapOctokitError(error, "PATCH", `/repos/${input.owner}/${input.repo}/issues/comments/${input.commentId}`);
    }
}
/** Reply to an inline pull-request review comment thread. */
export async function createGitHubReviewCommentReply(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = await octokit.rest.pulls.createReplyForReviewComment({
            owner: input.owner,
            repo: input.repo,
            pull_number: input.pullRequestNumber,
            comment_id: input.commentId,
            body: input.body,
        });
        return toPostedComment(response.data);
    }
    catch (error) {
        throw wrapOctokitError(error, "POST", `/repos/${input.owner}/${input.repo}/pulls/${input.pullRequestNumber}/comments/${input.commentId}/replies`);
    }
}
/** Create a reaction on an issue or review comment. */
export async function createGitHubReaction(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = input.subject === "issue_comment"
            ? await octokit.rest.reactions.createForIssueComment({
                owner: input.owner,
                repo: input.repo,
                comment_id: input.commentId,
                content: input.content,
            })
            : await octokit.rest.reactions.createForPullRequestReviewComment({
                owner: input.owner,
                repo: input.repo,
                comment_id: input.commentId,
                content: input.content,
            });
        return {
            body: response.data,
            ok: true,
            status: response.status,
        };
    }
    catch (error) {
        const segment = input.subject === "issue_comment" ? "issues/comments" : "pulls/comments";
        throw wrapOctokitError(error, "POST", `/repos/${input.owner}/${input.repo}/${segment}/${input.commentId}/reactions`);
    }
}
/** Create a commit status (legacy `statuses` API). */
export async function createGitHubCommitStatus(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = await octokit.rest.repos.createCommitStatus({
            owner: input.owner,
            repo: input.repo,
            sha: input.sha,
            state: input.state,
            ...(input.context === undefined ? {} : { context: input.context }),
            ...(input.description === undefined ? {} : { description: input.description }),
            ...(input.targetUrl === undefined ? {} : { target_url: input.targetUrl }),
        });
        return {
            body: response.data,
            ok: true,
            status: response.status,
        };
    }
    catch (error) {
        throw wrapOctokitError(error, "POST", `/repos/${input.owner}/${input.repo}/statuses/${input.sha}`);
    }
}
/** Create a check run (Checks API). */
export async function createGitHubCheckRun(input) {
    const octokit = await createGitHubOctokit(input);
    const now = new Date().toISOString();
    try {
        const response = await octokit.rest.checks.create({
            owner: input.owner,
            repo: input.repo,
            name: input.name,
            head_sha: input.sha,
            status: input.status,
            started_at: now,
            ...checkRunCompletionFields(input, now),
            ...checkRunDetailsUrl(input),
            ...checkRunOutput(input),
        });
        return toCheckRun(response.data);
    }
    catch (error) {
        throw wrapOctokitError(error, "POST", `/repos/${input.owner}/${input.repo}/check-runs`);
    }
}
/** Update a check run (Checks API). */
export async function updateGitHubCheckRun(input) {
    const octokit = await createGitHubOctokit(input);
    try {
        const response = await octokit.rest.checks.update({
            owner: input.owner,
            repo: input.repo,
            check_run_id: input.checkRunId,
            name: input.name,
            status: input.status,
            ...checkRunCompletionFields(input, new Date().toISOString()),
            ...checkRunDetailsUrl(input),
            ...checkRunOutput(input),
        });
        return toCheckRun(response.data);
    }
    catch (error) {
        throw wrapOctokitError(error, "PATCH", `/repos/${input.owner}/${input.repo}/check-runs/${input.checkRunId}`);
    }
}
function checkRunCompletionFields(input, completedAt) {
    if (input.status !== "completed" || input.conclusion === undefined) {
        return {};
    }
    return { completed_at: completedAt, conclusion: input.conclusion };
}
function checkRunDetailsUrl(input) {
    return input.detailsUrl === undefined ? {} : { details_url: input.detailsUrl };
}
function checkRunOutput(input) {
    return input.output === undefined ? {} : { output: input.output };
}
function toCheckRun(raw) {
    return {
        htmlUrl: typeof raw.html_url === "string" ? raw.html_url : undefined,
        id: typeof raw.id === "number" ? raw.id : 0,
        raw,
    };
}
function toPostedComment(raw) {
    return {
        htmlUrl: typeof raw.html_url === "string" ? raw.html_url : undefined,
        id: typeof raw.id === "number" ? raw.id : 0,
        raw,
        url: typeof raw.url === "string" ? raw.url : undefined,
    };
}
function normalizeRequestPath(path) {
    return path.startsWith("/") ? path : `/${path}`;
}
function isOctokitRequestError(error) {
    return (typeof error === "object" &&
        error !== null &&
        "status" in error &&
        typeof error.status === "number");
}
/** Normalize an Octokit request failure into {@link GitHubApiError}. */
export function wrapOctokitError(error, method, path) {
    if (isOctokitRequestError(error)) {
        return new GitHubApiError({
            body: error.response?.data,
            method,
            path,
            status: error.status,
        });
    }
    return error instanceof Error ? error : new Error(String(error));
}
